import json

def parse_progress(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError('Invalid JSON syntax') from error
    if not isinstance(data, dict):
        raise ValueError('Expected a JSON object')
    lesson = data.get('lesson_id')
    minutes = data.get('minutes')
    if not isinstance(lesson, str) or not lesson.strip():
        raise ValueError('lesson_id must be non-empty text')
    if type(minutes) is not int or minutes < 0:
        raise ValueError('minutes must be a non-negative integer')
    return {'lesson_id': lesson.strip(), 'minutes': minutes}

print(parse_progress('{"lesson_id": " loops ", "minutes": 25}'))

